        long id,
        String name,
        String email,
        boolean active,
        Instant createdAt,
        List<String> roles) {
}

package com.example.json;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;

import java.time.Instant;
import java.util.List;
import java.util.Map;

public final class JsonDemo {

    private static final ObjectMapper MAPPER = new ObjectMapper()
            .registerModule(new JavaTimeModule())
            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
            .disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);

    public static String toJson(Object value) {
        try {
            return MAPPER.writeValueAsString(value);
        } catch (Exception e) {
            throw new JsonException("Failed to serialize to JSON", e);
        }
    }

    public static String toPrettyJson(Object value) {
        try {
            return MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(value);
        } catch (Exception e) {
            throw new JsonException("Failed to serialize to JSON", e);
        }
    }

    public static <T> T fromJson(String json, Class<T> type) {
        try {
            return MAPPER.readValue(json, type);
        } catch (Exception e) {
            throw new JsonException("Failed to deserialize JSON", e);
        }
    }

    public static <T> T fromJson(String json, TypeReference<T> type) {
        try {
            return MAPPER.readValue(json, type);
        } catch (Exception e) {
            throw new JsonException("Failed to deserialize JSON", e);
        }
    }

    public static void main(String[] args) {
        User user = new User(
                42L,
                "Ada Lovelace",
                "ada@example.com",
                true,
                Instant.parse("2026-01-15T10:30:00Z"),
                List.of("admin", "developer"));

        String json = toPrettyJson(user);
        System.out.println("Generated JSON:");
        System.out.println(json);

        User parsed = fromJson(json, User.class);
        System.out.println("Parsed back: " + parsed);

        String raw = "{\"name\":\"Grace Hopper\",\"languages\":[\"COBOL\",\"FLOW-MATIC\"]}";
        Map<String, Object> tree = fromJson(raw, new TypeReference<>() {
        });
        System.out.println("Parsed generic JSON: " + tree);
    }

    private JsonDemo() {
    }
}

package com.example.json;

public class JsonException extends RuntimeException {

    public JsonException(String message, Throwable cause) {
        super(message, cause);
    }
}

package com.example.json;

import com.fasterxml.jackson.core.type.TypeReference;
import org.junit.jupiter.api.Test;

import java.time.Instant;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class JsonDemoTest {

    @Test
    void roundTripsTypedObject() {
        User user = new User(
                7L,
                "Alan Turing",
                "alan@example.com",
                true,
                Instant.parse("2026-02-01T08:00:00Z"),
                List.of("researcher"));

        User parsed = JsonDemo.fromJson(JsonDemo.toJson(user), User.class);

        assertEquals(user, parsed);
    }

    @Test
    void parsesIntoGenericMap() {
        Map<String, Object> parsed = JsonDemo.fromJson(
                "{\"name\":\"Grace\",\"active\":true}",
                new TypeReference<>() {
                });

        assertEquals("Grace", parsed.get("name"));
        assertEquals(true, parsed.get("active"));
    }

    @Test
    void ignoresUnknownProperties() {
        User parsed = JsonDemo.fromJson(
                "{\"id\":1,\"name\":\"n\",\"email\":\"e\",\"active\":false,"
                        + "\"createdAt\":\"2026-01-01T00:00:00Z\",\"roles\":[],\"extra\":123}",
                User.class);

        assertEquals(1L, parsed.id());
        assertTrue(parsed.roles().isEmpty());
    }
}
